"""Addressed examples for the first course; existing seminar solutions are retained."""
from reviewed_course_examples import e

EXAMPLES = {
 'History of Cryptography': e('Отправитель передаёт слово ABBA. Сначала используется фиксированная замена A→B,B→A; затем та же задача рассматривается с меняющимся секретным ключом.', ('При фиксированной замене получается BAAB. Наблюдатель, узнав таблицу, сразу восстанавливает ABBA.', 'При семействе таблиц знание устройства ещё не сообщает, какая таблица выбрана. Повторы, однако, сохраняются: позиции 1 и 4 равны, как и 2 и 3.'), 'На одном сообщении виден переход от секретности устройства к секретности ключа.', 'Секретный ключ и известное описание алгоритма — разные данные; знание одного не тождественно знанию другого.', 'Этот сценарий поясняет принцип, а не доказывает стойкость исторической замены и не реконструирует конкретное историческое событие.'),
 'Cryptosystem and Security Goals': e('Алиса передаёт Бобу один бит команды M=0; общий учебный ключ K=1; C=M XOR K. Противник может менять передаваемый бит.', ('Алиса получает C=1. Боб без вмешательства расшифровывает 1 XOR 1=0.', 'Противник инвертирует C на 0; Боб получает 0 XOR 1=1 и не замечает изменения по одному шифрованию.'), 'Корректное шифрование восстановило сообщение, но не обеспечило целостность при активном вмешательстве.', 'Оба возможных сообщения восстанавливаются своим ключом, однако модификация шифртекста меняет команду.', 'Это учебный XOR, не прикладная схема. Для защиты от изменения нужна аутентификация, а для доступности — отдельные меры.'),
 'Symmetric-Key Cryptography': e('Оба участника знают учебный трёхбитный K=101; сообщение M=011; преобразование — XOR.', ('Шифрование: 011 XOR 101=110.', 'Расшифрование: 110 XOR 101=011. Участник с другим K=100 получит 010.'), 'Правильный общий ключ восстановил сообщение, неправильный дал другое значение.', 'Побитно K XOR K=000, поэтому повторный XOR отменяет первый.', 'Малый ключ и повторное применение XOR-гаммы небезопасны. Пример показывает симметрию ключа, а не практический шифр.'),
 'Asymmetric Cryptography': e('Игрушечное ядро RSA: публичные n=33,e=3; закрытый показатель d=7; сообщение m=4.', ('Шифрование открытым ключом: 4³=64≡31 mod 33.', 'Получатель вычисляет 31²≡4, 31⁴≡16; 31⁷≡16·4·31≡4 mod 33.'), 'Отправитель использовал (33,3), получатель — закрытый показатель 7.', 'ed=21≡1 mod phi(33)=20; этот маленький пример корректен.', 'Это не безопасная реализация RSA: модуль мгновенно факторизуется, отсутствует кодирование сообщения. Различие ключей не означает защиту от подмены открытого ключа.'),
 'Cryptanalysis': e('Известно, что шифр — сдвиг y=x+k mod 26. Наблюдателю известна пара A→D, то есть 0→3.', ('Восстановить k=3−0=3 mod 26.', 'Проверить на дополнительной паре C→F: 2+3=5. Затем расшифровать K: 10−3=7, то есть H.'), 'Ключ получен из известного открытого текста, а не полным перебором.', 'Дополнительная пара согласуется с тем же k; одна ошибочная пара могла бы дать ложный ключ.', 'Сценарий предполагает знание семейства шифров и корректной пары. Для современного нелинейного шифра это уравнение неприменимо.'),
 'Algebraic Structures': e('Операция a*b=3a−2b на вещественных числах; x=1,y=2,z=−1.', ('y*z=6+2=8, затем x*8=3−16=−13.', 'x*y=3−4=−1, затем (−1)*z=−3+2=−1.'), 'Две расстановки скобок дали −13 и −1: ассоциативности нет.', 'Подстановка в раскрытые выражения 3x−6y+4z и 9x−6y−2z даёт те же значения.', 'Один контрпример достаточен для опровержения ассоциативности; несколько совпадений не доказывают её для всех вещественных чисел.', 'Семинар 01, стр. 1–3; подробная подстановка в пример курса.'),
 'Permutation Groups': e('Два независимых цикла pi=(1 2 3)(4 5). Композиции действуют на элементы справа налево.', ('Первый цикл возвращается через 3 шага, второй через 2; общий возврат через lcm(3,2)=6.', 'Для pi^5 показатель первого цикла 5 mod 3=2, второго 5 mod 2=1: pi^5=(1 3 2)(4 5).'), 'Порядок pi равен 6; pi^5 — обратная перестановка.', 'pi^5·pi=pi^6=id; элемент 1 идёт pi в 2, затем pi^5 обратно в 1.', 'Складывать длины циклов нельзя: 3+2=5 не является порядком. Формула НОК относится к разложению на непересекающиеся циклы.'),
 'Rings and Modular Arithmetic': e('Решить 112x≡9 mod 423.', ('Алгоритм Евклида: 423=3·112+87; 112=87+25; 87=3·25+12; 25=2·12+1.', 'Обратная подстановка: 1=25−2(87−3·25)=7·25−2·87=7·112−9·87=34·112−9·423.', 'Поэтому x≡34·9=306 mod 423.'), 'Все решения x=306+423t при целом t.', '112·306=34272=81·423+9.', 'Обратный элемент существует потому, что НОД равен 1. Для 6x≡1 mod 15 решений нет.', 'Семинар 08, стр. 1–2; раскрыта обратная подстановка.'),
 'Polynomial Rings': e('Делим a=X³+X+1 на b=X+1 над F2, где 1+1=0.', ('Первый член частного X²: a−X²b=X²+X+1.', 'Следующий член X: вычесть Xb=X²+X, останется 1.'), 'q=X²+X, r=1; степень остатка меньше степени b.', 'Раскрытие (X²+X)(X+1)+1=X³+2X²+X+1=X³+X+1 в F2.', 'Над вещественными числами промежуточные знаки и результат были бы другими. Нулевой многочлен не может быть делителем.'),
 'Finite Fields': e('Поле F3[X]/(2X²−2X+1). Обозначим класс X через x.', ('Значения многочлена в 0,1,2: 1,1,2 mod 3 — корней нет; для степени 2 это доказывает неприводимость.', 'Из 2x²−2x+1=0 умножением на 2 получаем x²=x+1.', 'x³=x²+x=2x+1; x⁴=2x²+x=3x+2=2; x⁸=4=1.'), 'В поле 9 элементов; x имеет порядок 8, поскольку x⁴=2≠1, x²≠1 и x≠1.', 'Делители 8 равны 1,2,4,8; первые три исключены, поэтому порядок именно 8.', 'Если взять приводимый модуль, получится кольцо с делителями нуля, не поле.', 'Семинар 05, стр. 1–5; вычисления из конструкции курса.'),
 'Elliptic Curves': e('Кривая y²=x³+2x+2 над F17; точка P=(5,1). Рассчитываем 2P.', ('Проверить точку: 1²=1, 5³+2·5+2=137≡1 mod 17.', 'Наклон lambda=(3·5²+2)/(2·1)=77·2^{-1}≡9·9≡13 mod 17.', 'x2=13²−2·5=159≡6; y2=13(5−6)−1=−14≡3.'), '2P=(6,3).', '3²=9, 6³+2·6+2=230≡9 mod 17. Дискриминант: 4·2³+27·2²=140≡4≠0.', 'Если y=0, знаменатель 2y нулевой: удвоение даёт точку на бесконечности, обычная дробь не применяется.'),
 'Elliptic Curve Cryptography': e('Та же учебная кривая F17: y²=x³+2x+2; P=(5,1), секретный скаляр d=3, 2P=(6,3).', ('Сложить P и 2P: lambda=(3−1)/(6−5)=2.', 'x3=2²−5−6=−7≡10; y3=2(5−10)−1=−11≡6.'), 'Открытая точка Q=3P=(10,6).', '6²≡2 mod 17; 10³+20+2=1022≡2. Q лежит на кривой.', 'd=3 и поле из 17 элементов выбраны для ручного расчёта, не для защиты. Проверка принадлежности кривой не заменяет проверку порядка подгруппы в реальном протоколе.'),
 'Euclidean Algorithm': e('Числа курса 3931 и 1148.', ('Деления: 3931=3·1148+487; 1148=2·487+174; 487=2·174+139; 174=139+35; 139=3·35+34; 35=34+1.', 'Назад: 1=4·35−139=4·174−5·139=14·174−5·487=14·1148−33·487=113·1148−33·3931.'), 'НОД=1; обратный к 1148 mod 3931 равен 113.', '113·1148−33·3931=129724−129723=1.', 'Если последний ненулевой остаток больше 1, коэффициенты Безу всё ещё существуют, но обратного по этому модулю нет.', 'Семинар 07, стр. 1–2; полный обратный ход.'),
 'Euler Totient and Fermat-Euler Theorems': e('n=15, a=2.', ('Единицы mod 15: 1,2,4,7,8,11,13,14; phi(15)=8.', '2⁴=16≡1, поэтому 2⁸≡1 mod 15.'), 'Теорема Эйлера выполнена; порядок 2 равен 4, а не обязательно phi(15)=8.', '2²=4≠1 и 2⁴=1: минимальный положительный показатель возврата 4.', 'Для a=3 условие gcd(a,15)=1 нарушено: 3⁸ mod 15=6, не 1.'),
 'Chinese Remainder Theorem': e('x≡2 mod 15, x≡5 mod 13, x≡3 mod 7; модули попарно взаимно просты.', ('N=1365; N1=91,N2=105,N3=195. Остатки по соответствующим модулям 1,1,6, обратные 1,1,6≡−1.', 'Сумма 2·91+5·105−3·195=182+525−585=122.'), 'x≡122 mod 1365.', '122=8·15+2=9·13+5=17·7+3.', 'Для невзаимно простых модулей нельзя применять эту формулу без проверки совместимости; x≡0 mod 2 и x≡1 mod 4 несовместимы.', 'Семинар 09, стр. 1–2; проверены коэффициенты и остатки.'),
 'Quadratic Residues and Modular Square Roots': e('Решить x²≡811 mod 1457, где 1457=31·47.', ('811 mod 31=5, корни 6 и 25=−6; 811 mod 47=12, корни 24 и 23=−24.', '−3·31+2·47=1. Склеить: 6·94+24·(−93)=−1668≡1246; 6·94−24·(−93)=2796≡1339.', 'Добавить противоположные остатки: −1246≡211, −1339≡118.'), 'Четыре различных корня: 118,211,1246,1339.', 'Квадрат каждого по модулю 1457 равен 811. На странице 3 семинара 11 и в прежнем конспекте запись «1246, −211, 1339, −118» повторяла два класса вместо четырёх. Опечатка источника исправлена явно: противоположные остатки равны 211 и 118, без минуса.', 'Число четыре относится к ненулевому квадрату по произведению двух разных нечётных простых; вырожденные случаи требуют отдельного разбора.', 'Семинар 11, стр. 1–3; исправлена опечатка знаков источника, подтверждённая по отрендеренной странице 3.'),
 'Modular Exponentiation': e('Вычислить 7¹³ mod 23; 13=8+4+1.', ('7²=49≡3, 7⁴≡3²=9, 7⁸≡9²=81≡12.', 'Перемножить выбранные степени: 12·9·7=756≡20 mod 23.'), '7¹³ mod 23=20.', 'Прямое возведение и взятие остатка дают тот же результат; промежуточные числа сокращались на каждом шаге.', 'При e=0 результат 1 mod n, включая 0 при n=1. Для криптографической реализации ветвления по секретным битам показателя требуют защиты от утечек.'),
 'Integer Factorization and Pollard Rho': e('n=91, f(x)=x²+1 mod 91; Флойд: x=y=2, x делает один шаг, y — два.', ('Итерация 1: x=5,y=26; gcd(21,91)=7.', 'Разделить 91 на 7, получить второй множитель 13.'), '91=7·13.', '7·13=91; найденный НОД строго между 1 и 91.', 'Если НОД равен 1, итерации продолжают; если 91 — эта попытка не дала множитель, нужна смена начального состояния или f. Одна удачная итерация не характеризует среднюю сложность.'),
 'Discrete Logarithm and Baby-Step Giant-Step': e('Найти x: 2^x≡13 mod 23; работать в группе порядка 11, m=ceil(√11)=4.', ('Малые шаги j=0…3: 2^j=[1,2,4,8]. 2^4=16, обратный к 16 mod 23 равен 13.', 'Большие шаги 13·13^i mod 23: при i=0 —13, i=1 —8. Значение 8 совпало с малым шагом j=3.', 'x=im+j=1·4+3=7.'), 'Дискретный логарифм x=7 mod 11.', '2⁷=128≡13 mod 23.', 'Нужно искать в согласованной подгруппе и знать границу порядка. Для элемента вне неё совпадения может не быть.'),
 'Primality Testing and Miller-Rabin': e('n=21, основание a=2; n−1=20=2²·5.', ('x=2⁵ mod 21=32 mod 21=11; это ни 1, ни 20.', 'Один последующий квадрат: 11² mod 21=16; значение 20 не получено.'), 'Основание 2 свидетельствует, что 21 составное.', '21=3·7 подтверждает решение независимо от теста.', 'Прохождение одного основания не доказывает простоту. Чётные n>2 отвергаются до этой процедуры; n=2 обрабатывается отдельно.'),
 'Block Cipher Design': e('Игрушечный раунд Фейстеля с 4-битными половинами L=1010,R=0110 и F(R)=R XOR 0011.', ('F(0110)=0101. Новая левая половина L-prime=R=0110.', 'Правая R-prime=L XOR F(R)=1010 XOR 0101=1111.', 'Назад R=L-prime=0110; L=R-prime XOR F(L-prime)=1111 XOR 0101=1010.'), 'Один раунд обратим и восстановил обе половины.', 'Для обращения не понадобилось инвертировать F: два XOR с одним значением взаимно уничтожаются.', 'Один раунд и линейная F не обеспечивают стойкость. Пример иллюстрирует конструкцию, не DES или современный шифр.'),
 'DES and Triple DES': e('Сценарий проверки конфигурации: система заявляет 3DES EDE, но все три ключа равны одному учебному K.', ('Преобразование имеет вид E_K(D_K(E_K(P))).', 'Внутренняя пара D_K(E_K(P)) возвращает P; остаётся E_K(P).'), 'Тройное применение выродилось в одно DES-шифрование.', 'Достаточно свойства D_K∘E_K=id; конкретные байты ключа для доказательства не нужны.', 'Из этого не следует, что разные ключи дают 168 бит эффективной стойкости. Пример не рекомендует DES/3DES для новых систем.'),
 'Advanced Encryption Standard': e('Один шаг MixColumns AES. Входной столбец в hex: [db,13,53,45]; арифметика GF(2⁸) с модулем 0x11b.', ('Умножения на 2: db→ad,13→26,53→a6,45→8a. Умножение на 3 — XOR результата на 2 с исходным байтом: 76,35,f5,cf.', 'Первая строка: ad XOR 35 XOR 53 XOR 45=8e. Вторая: db XOR 26 XOR f5 XOR 45=4d.', 'Третья: db XOR 13 XOR a6 XOR cf=a1. Четвёртая: 76 XOR 13 XOR 53 XOR 8a=bc.'), 'Выходной столбец [8e,4d,a1,bc].', 'Обратная матрица с первой строкой [0e,0b,0d,09] и циклическими сдвигами возвращает [db,13,53,45]; тест вычисляет это отдельно.', 'Здесь только MixColumns, не полный раунд или AES. Последний раунд MixColumns не содержит; обычное целочисленное умножение байтов неприменимо. Проверка определения: [FIPS 197, §4.2 и §5.1.3](https://nvlpubs.nist.gov/nistpubs/FIPS/NIST.FIPS.197-upd1.pdf).'),
 'Kuznyechik': e('Рассмотрим только XOR-слой X[k] в Кузнечике: 128-битное состояние из нулей, учебный ключ из 16 байтов 01.', ('Побайтно 00 XOR 01=01; результат — 16 байтов 01.', 'Повторно применить тот же слой: 01 XOR 01=00 для каждого байта.'), 'Слой X[k] обратим сам себе.', 'Длина до/после 128 бит; X[k](X[k](a))=a.', 'Это не тест-вектор всего Кузнечика: S-преобразование, линейный слой и развёртка ключа здесь не выполняются. Пример показывает роль добавления ключа.'),
 'Magma': e('Только сложение с подключом перед подстановками Магмы. Правая половина a=0xfffffffe, подключ k=0x00000005, оба 32-битные.', ('Обычная сумма равна 0x100000003.', 'Взять остаток по 2³²: отбросить перенос за 32 бита, получить 0x00000003.'), 'Во вход подстановок попадёт 32-битное 00000003.', '3−5 mod 2³²=0xfffffffe, то есть сложение обратимо до последующих слоёв.', 'XOR дал бы fffffffb, другой результат. Это не полный раунд: подстановки, циклический сдвиг и операция Фейстеля ещё не выполнены.'),
 'Block Cipher Modes': e('Учебный 4-битный блочный примитив E(x)=x XOR 9, D=E; CBC, IV=3, блоки P1=5,P2=6.', ('C1=E(5 XOR 3)=E(6)=15.', 'C2=E(6 XOR 15)=E(9)=0.', 'Назад P1=D(15) XOR 3=6 XOR 3=5; P2=D(0) XOR 15=9 XOR 15=6.'), 'CBC дал блоки [15,0], обратная цепочка вернула [5,6].', 'Если ошибочно заменить IV=3 на IV=2, первый восстановленный блок станет 4, второй останется 6.', 'Игрушечный E нестоек; CBC сам по себе не проверяет целостность. Паддинг не нужен только потому, что вход уже разбит на полные блоки.'),
 'Cryptographic Hash Functions': e('Учебная выходная длина n=8 бит, равномерная модель случайного хеша. Берём q=16 различных сообщений.', ('Число пар 16·15/2=120; вероятность совпадения одной пары 1/256.', 'Ожидаемое число совпавших пар 120/256=0.46875. Приближение вероятности хотя бы одной коллизии 1−exp(−0.46875)≈0.374.'), 'Порядок √256=16 запросов уже создаёт заметный риск коллизии.', 'Для q=1 пар нет и вероятность коллизии нулевая.', 'Это вероятностная модель, не расчёт конкретного SHA/Стрибога и не гарантия коллизии ровно на 16-м сообщении. Поиск прообраза — другая задача.'),
 'Streebog': e('Проверяем совместимость интерфейсов: отправитель использует Стрибог-256, проверяющий ожидает Стрибог-512.', ('Первый результат содержит 256/8=32 байта, второй формат — 512/8=64 байта.', 'В hex это 64 и 128 знаков соответственно. Проверяющий сначала сравнивает объявленный вариант и длину.'), 'Результат 32 байта нельзя принять как корректный результат варианта 512.', 'Даже ведущие нули не сокращают фиксированную длину; их нужно сохранять при кодировании.', 'Обрезать Стрибог-512 до 32 байт не значит вычислить Стрибог-256: варианты используют разные начальные состояния. Сценарий не вычисляет сам хеш.'),
 'Message Authentication Codes': e('Алиса и Боб делят ключ MAC. Алиса вычислила t=MAC_K(«сумма=100»); противник меняет сообщение на «сумма=900», оставляя t.', ('Боб вычисляет MAC_K от полученного «сумма=900».', 'Если пересчитанный тег не совпадает с t, сообщение отвергается до обработки команды. Для конкретного сценария считаем, что совпадения нет.'), 'Модифицированная команда не выполняется.', 'Неизменная пара сообщения и тега проходит тем же ключом; другой ключ не должен использоваться незаметно.', 'MAC не скрывает сумму. Повтор исходной корректной пары может пройти: защита от повторов требует счётчика/контекста в аутентифицируемом сообщении.'),
 'RSA': e('Учебные p=11,q=13,n=143; phi=120; e=7,d=103; m=9.', ('Проверить 7·103=721≡1 mod 120.', '9²≡81,9⁴≡126,9⁷≡126·81·9≡48 mod 143.', 'Для расшифрования: 48²≡16,48⁴≡113,48⁸≡42,48¹⁶≡48,48³²≡16,48⁶⁴≡113. Поскольку 103=64+32+4+2+1, произведение 113·16·113·16·48 mod 143=9.'), 'm=9 зашифровалось в 48 и восстановилось.', 'Прямой модульный расчёт pow(48,103,143) даёт 9.', 'Это учебное ядро без безопасного кодирования. m должен быть 0…142; одинаковый m при сыром RSA даёт одинаковый c.'),
 'Rabin Cryptosystem': e('n=77=7·11, m=20; шифрование c=m² mod n.', ('20² mod 77=400 mod 77=15.', 'Корни 15 mod 7=1: 1 и 6; mod 11=4: 2 и 9. Перебор допустимых классов подтверждает корни 13,20,57,64.'), 'Четыре кандидата сообщения соответствуют одному c=15.', '13²=169≡15,20²≡15,57²≡15,64²≡15 mod 77.', 'Само извлечение квадратного корня не выбирает исходное 20. Протокол должен однозначно кодировать сообщение и учитывать активные атаки.'),
 'ElGamal Cryptosystem': e('Учебная группа mod 23: g=5, закрытый x=6, открытый y=5⁶ mod 23=8; m=10, одноразовый k=3.', ('c1=5³ mod 23=10; общий множитель y³=8³ mod 23=6.', 'c2=10·6 mod 23=14.', 'Получатель вычисляет c1^x=10⁶ mod 23=6; обратный к 6 —4. m=14·4 mod 23=10.'), 'Шифртекст (10,14) восстановил m=10.', 'Обе стороны получили множитель 6 независимыми способами.', 'Повтор k повторяет множитель и раскрывает отношения сообщений. Малые числа и сырой ElGamal здесь не подходят для защиты.'),
 'Diffie-Hellman Key Exchange': e('p=23,g=5; Алиса x=6, Боб y=15.', ('Алиса отправляет A=5⁶ mod 23=8; Боб B=5¹⁵ mod 23=19.', 'Алиса вычисляет 19⁶ mod 23=2; Боб 8¹⁵ mod 23=2.'), 'Получен один общий секрет 2.', '19²≡16,19⁴≡3,19⁶≡3·16≡2. Значение совпадает с модульным расчётом стороны Боба.', 'Без аутентификации сообщений A/B посредник может согласовать отдельные секреты с каждой стороной. Числа учебные.'),
 'Digital Signatures': e('Алиса подписала документ D и отправила (D,s). Боб заранее доверяет её открытому ключу pk.', ('Боб проверяет Verify(pk,D,s); корректная пара даёт 1.', 'После замены D на D-prime тот же s проверяется уже с другими байтами; в сценарии Verify(pk,D-prime,s)=0.'), 'Изменённый документ отвергнут без знания закрытого ключа.', 'Проверка использует точные байты, а не только визуальный вид документа; изменение кодировки тоже может изменить результат.', 'Подпись не скрывает документ. Если pk подменён, успешная проверка не подтверждает личность Алисы.'),
 'Schnorr Signatures': e('Учебная подгруппа порядка q=11 mod p=23; g=2; секрет x=3, открытый Y=8; nonce r=4. Для примера хеш-вызов возвращает e=5.', ('R=2⁴ mod 23=16; s=(r+xe) mod 11=(4+15) mod 11=8.', 'Проверка: g^s=2⁸ mod 23=3. Правая часть R·Y^e=16·8⁵ mod 23=16·16 mod 23=3.'), 'Пара (R=16,s=8) проходит уравнение проверки при e=5.', 'Обе стороны уравнения равны 3. Реальный проверяющий обязан пересчитать e=H(R||m), здесь значение хеша задано для ручного расчёта.', 'Повтор r на другом сообщении раскрывает x из разности s. Малые параметры и заданный e не образуют безопасную подпись.'),
 'Random Number Generation and Entropy': e('Два независимых бита X1,X2 с P(0)=0.6=0.5+Delta, Delta=0.1.', ('XOR равен нулю при 00 или 11: 0.6²+0.4²=0.36+0.16=0.52.', 'По формуле 0.5+2Delta²=0.5+0.02=0.52.'), 'Смещение уменьшилось с 0.1 до 0.02, но не исчезло.', 'Если X2=X1, XOR всегда ноль: вероятность 1, а не 0.52. Независимость существенна.', 'Уменьшение смещения не доказывает непредсказуемость генератора. Энтропию нельзя получить из полностью известного детерминированного состояния.'),
 'Stream Ciphers and One-Time Pad': e('M1=1010, одноразовая гамма K=0110.', ('C1=M1 XOR K=1100; обратно 1100 XOR 0110=1010.', 'Если той же гаммой зашифровать M2=0011, получится C2=0101; C1 XOR C2=1001=M1 XOR M2.'), 'Один цикл обратим, повтор гаммы раскрывает связь двух сообщений.', 'При известном M1 можно найти M2=(C1 XOR C2) XOR M1=0011.', 'Совершенная секретность требует независимой равномерной гаммы нужной длины и однократного использования. Потоковый шифр обычно растягивает короткий ключ и имеет другую модель стойкости.'),
 'Cryptographic Key Management': e('Сервис хранит зашифрованные записи с идентификатором ключа v1; требуется перейти на v2 без потери чтения старых данных.', ('Создать v2 и направить новые записи на него. Старые записи продолжают помечаться v1.', 'Перешифровать старые записи и проверить расшифрование каждой. Убедиться, что активных ссылок на v1 не осталось.', 'Вывести v1 из активного использования; срок сохранения резервных копий определить отдельно.'), 'Новые и мигрированные записи читаются через v2; старый ключ не используется для новых операций.', 'Контрольный набор: запись до ротации, запись во время и запись после неё — каждая расшифровывается ожидаемой версией.', 'Немедленное удаление v1 до миграции делает старые данные недоступными. Это сценарий жизненного цикла, не инструкция удаления реальных ключей.'),
 'Public Key Infrastructure and X.509': e('Цепочка: доверенный корень R → промежуточный I → серверный сертификат S для kb.example. Клиент открывает kb.example.', ('Проверить подпись S ключом I и подпись I ключом R; R должен быть в доверенном хранилище.', 'Проверить сроки, ограничения CA, назначение ключа и соответствие имени kb.example. Заданная политика отзыва также должна быть выполнена.'), 'Только при выполнении всех условий цепочка подтверждает ключ нужного сервера.', 'Для имени other.example тот же S отклоняется даже с корректными подписями.', 'Цепочка действительных подписей без проверки имени не аутентифицирует нужный узел. Сценарий не подтверждает актуальность какого-либо реального сертификата.'),
 'Certificate Enrollment Protocols': e('Устройство создало пару ключей и запрос CSR на сертификат для device-17; регистрационная система знает разрешённое имя.', ('Устройство подписывает CSR своим закрытым ключом: это доказательство владения, а не права на имя.', 'Регистратор сопоставляет запрос с разрешённой идентичностью device-17; CA выпускает сертификат только после проверки.', 'Устройство проверяет, что в сертификате его открытый ключ и согласованное имя, затем устанавливает цепочку.'), 'Сертификат связывает проверенное имя с ключом запроса.', 'CSR с тем же корректным доказательством владения, но чужим именем должен быть отклонён.', 'Автоматизация выпуска не отменяет проверки полномочий. Подробные сообщения SCEP/EST/CMP различаются; этот сценарий показывает общий процесс.'),
 'Cryptographic Protocols and Authenticated Key Exchange': e('Алиса и Боб согласуют эфемерные ключи, но активный посредник может заменять сообщения.', ('Связать публичные значения обмена, идентификаторы сторон и выбранные алгоритмы в один транскрипт.', 'Проверить аутентификацию этого транскрипта и подтверждение полученного ключа до передачи прикладной команды.'), 'При подмене публичного значения транскрипты расходятся и проверка должна завершиться отказом.', 'Успешное вычисление общего числа без проверки транскрипта не считается завершённым аутентифицированным обменом.', 'Это критерии сценария, не новый самодельный протокол. Для эксплуатации выбирается готовый проверенный протокол.'),
 'Hardware Security Modules': e('Сервис должен подписывать документы; ключ создан внутри HSM и помечен неэкспортируемым.', ('Приложение передаёт запрос подписи через разрешённый интерфейс; HSM проверяет право операции и возвращает подпись, не закрытый ключ.', 'Проверяющий вне HSM проверяет подпись открытым ключом. Попытка экспорта секретного материала по политике отвергается.'), 'Приложение получает результат операции без извлечения ключа.', 'Проверяются два разных свойства: подпись валидна и экспорт запрещён. Одно не доказывает другое.', 'Компрометированное авторизованное приложение может запрашивать нежелательные подписи. Неэкспортируемость не заменяет контроль смысла операций.'),
 'Cryptographic Service Providers': e('Приложение просит провайдер выполнить подпись ключом с идентификатором A; ключ находится в аппаратном хранилище.', ('Провайдер разрешает идентификатор A в нужный объект ключа и проверяет поддержку алгоритма.', 'Операция передаётся хранилищу; возвращённая подпись и идентификатор алгоритма передаются приложению.', 'Отдельный проверяющий использует публичный ключ A и тот же формат подписи.'), 'Проверка проходит при согласованных ключе, алгоритме и кодировании.', 'Запрос неподдерживаемого алгоритма должен дать явную ошибку, а не незаметную замену.', 'Одинаковое название алгоритма не гарантирует одинаковое кодирование параметров и подписи у разных провайдеров.'),
 'Cryptographic Protection Systems': e('Два шлюза должны защищать только поток между сетями A и B; остальные потоки обрабатываются иной политикой.', ('Установить ключевой материал и правила выбора защищаемого потока.', 'Отправить тестовый пакет A→B и проверить, что он проходит через криптографическую обработку.', 'Отправить запрещённый поток и убедиться, что он отклонён, а не ушёл открыто.'), 'Защита подтверждена для выбранного потока и проверенного набора условий.', 'Наличие установленного криптопровайдера или сертификата само по себе не доказывает, что пакет был защищён.', 'Это модель проверки, не заявление о сертифицированности продукта. Версия, комплектность и условия эксплуатации проверяются отдельно.'),
 'GOST R 34.10-2012': e('Интегратор выбирает между профилями подписи с порядком подгруппы соответствующего размера; рассматриваем фиксированное представление компонентов r,s.', ('Для 256-битного профиля два компонента по 32 байта дают 64 байта без внешней оболочки.', 'Для 512-битного профиля два компонента по 64 байта дают 128 байт. Проверить выбранные параметры и порядок кодирования на обеих сторонах.'), 'Сырые длины 64 и 128 байт относятся к разным профилям.', 'Каждый компонент проверяется как целое в допустимом диапазоне, а длина контейнера не подменяет эту проверку.', 'ASN.1 или иной контейнер может добавить байты. Один только размер подписи не доказывает её корректность или соответствие стандарту.'),
 'GOST R 34.12-2015': e('Сообщение 24 байта; сравниваем блочные размеры Магмы и Кузнечика без выбора режима.', ('Магма: блок 64 бита=8 байт, сообщение содержит 24/8=3 полных блока.', 'Кузнечик: блок 128 бит=16 байт, один полный блок и остаток 8 байт.'), 'Одинаковое сообщение по-разному делится на блоки.', '3·8=24; 1·16+8=24.', 'Стандарт шифров не разрешает самовольно обрезать остаток. Его обработка зависит от режима и согласованного дополнения.'),
 'GOST R 34.13-2015': e('Режим использует 128-битный блочный примитив; вход 20 байт. Сравниваем обработку хвоста и выбор IV как отдельные параметры реализации.', ('Выделить полный блок 16 байт и остаток 4 байта.', 'Проверить выбранный режим по его правилам: допускает ли он неполный последний блок либо требует дополнения. Не считать наличие шифра ответом на этот вопрос.'), 'До выполнения операции зафиксированы режим, обработка хвоста и начальные параметры.', 'Тест включает входы 0,16,20 байт; восстановленный текст должен иметь исходную длину, без незаметно добавленных служебных байтов.', 'Этот сценарий не приписывает всем режимам один способ дополнения. Конкретный режим и его параметры должны быть названы до расчёта.'),
 'TLS': e('Клиент открывает kb.example; посредник предъявляет сертификат для other.example с корректной доверенной цепочкой.', ('Проверка цепочки подписей проходит.', 'Проверка имени обнаруживает несоответствие other.example ожидаемому kb.example; соединение не допускается к передаче прикладных данных.'), 'Доверенный издатель сам по себе не делает сертификат подходящим этому серверу.', 'Контрольная попытка с сертификатом kb.example проходит проверку имени при остальных выполненных условиях.', 'Сценарий иллюстрирует одно условие аутентификации, не полный TLS handshake и не настройку реального сервера.'),
 'IPsec': e('Получатель ESP уже принял пакет с номером 100; окно против повторов включает 98…100, номера 98 и 99 ещё не были приняты.', ('Пакет 99 с корректной аутентификацией находится в окне и ранее не отмечен: принять и отметить.', 'Повтор 99 отвергнуть; пакет 97 за левой границей отвергнуть по политике окна.'), 'Переставленный допустимый пакет принят, повтор и слишком старый пакет отвергнуты.', 'Битовая отметка номера обновляется после успешной проверки аутентификации, а не по неподтверждённому заголовку.', 'Размер окна 3 выбран для иллюстрации. Реальные размеры, расширенные номера и режимы задаются реализацией и профилем.'),
 'SSH': e('Для server.example заранее сохранён проверенный публичный ключ сервера A. При новом соединении предъявлен B.', ('Сравнить B с доверенной записью A: ключи отличаются.', 'Остановить аутентификацию сервера и проверить причину независимым каналом; не удалять запись автоматически.'), 'Сеанс с неподтверждённым новым ключом не используется.', 'При предъявлении A и корректной подписи обмена эта конкретная проверка проходит; далее всё ещё нужна аутентификация пользователя.', 'Первое сохранение неизвестного ключа без внешней проверки — TOFU, а не доказательство подлинности первого соединения.'),
 'Anonymous Communication Systems': e('Маршрут: клиент → входной узел → промежуточный → выходной → сайт. Канал до сайта дополнительно защищён TLS.', ('Входной узел наблюдает адрес клиента и следующий переход, но не должен получать весь маршрут из одного слоя.', 'Выходной наблюдает соединение с сайтом, но не исходный IP клиента непосредственно из предыдущего перехода.', 'Наблюдатель, видящий оба края, сопоставляет время и объём; шифрование содержимого не убирает эту возможность.'), 'Локальная видимость разделена между узлами, но глобальная корреляция остаётся ограничением.', 'Отдельно перечислены скрываемое содержимое и наблюдаемые метаданные.', 'Это модель маршрута, не гарантия анонимности конкретного продукта. Вход в личный аккаунт может связать действия независимо от сетевого маршрута.'),
 'Blockchain and Consensus': e('Два узла получили разные блоки на одной высоте: A и B. Правило учебной сети выбирает ветвь с большей накопленной работой.', ('Временно узел 1 хранит A, узел 2 —B.', 'Следующий блок продолжает A, её работа становится больше; узел 2 перестраивает активную цепь на ветвь A.'), 'Согласование состояния произошло после разрешения временной развилки.', 'Транзакция только из B больше не считается подтверждённой в выбранной цепи.', 'Правило зависит от протокола. Число блоков не всегда равно накопленной работе; сценарий не описывает все виды консенсуса.'),
 'Blockchain Cryptography': e('Блок B хранит хеш предшественника A. Участник изменил один байт транзакции в A.', ('Изменяется вход хеширования A; при отсутствии коллизии получается иной хеш.', 'Ссылка в B больше не совпадает с хешем изменённого A. Проверка цепочки обнаруживает рассогласование.'), 'Хеш-связь делает изменение предыдущего содержимого обнаружимым.', 'Если пересчитать и A, и ссылку B, структурная проверка может пройти; выбор допустимой истории всё ещё требует правил консенсуса.', 'Хеширование не устанавливает истинность сделки во внешнем мире и само по себе не запрещает переписывание всей цепочки.'),
 'Blockchain Attacks': e('Атакующий отправляет платёж T продавцу в публичную ветвь и конфликтующий T-prime себе в скрытую ветвь; обе тратят один выход.', ('Продавец принимает T после выбранного числа подтверждений.', 'В условном сценарии атакующему удаётся опубликовать ветвь с большей работой, где есть T-prime и нет T.', 'Узлы, следуя правилу выбора, принимают новую ветвь; продавец уже отдал товар.'), 'Один выход не принят дважды в одной итоговой цепи, но ранее принятый платёж отменён реорганизацией.', 'Проверка сценария отслеживает конфликтующий вход и смену активной ветви, а не только число узлов атакующего.', 'Создание множества идентичностей не равно получению большинства вычислительной работы. Исход атаки зависит от ресурсов и правил консенсуса.'),
 'Quantum Computing for Cryptography': e('Игрушечное пространство поиска из N=16 равноправных ключей; сравниваем порядки затрат классического перебора и квантового поиска.', ('Классический поиск проверяет до 16 кандидатов.', 'Масштаб квантового числа запросов к оракулу — √16=4, с константами и требованиями к когерентной реализации.'), 'Квадратичное уменьшение числа запросов не означает бесплатный физический поиск за четыре обычных операции.', 'Для N=2^k масштаб √N=2^(k/2), а не k/2 попыток.', 'Пример не моделирует ошибкокоррекцию, построение оракула и время устройства; он не предсказывает дату взлома реального ключа.'),
 'Quantum Key Distribution': e('После квантовой передачи и просеивания Алиса и Боб имеют четыре бита: 1011 и 1001.', ('Раскрыть для контроля третью позицию: 1 против 0, обнаружено расхождение.', 'Раскрытый бит больше нельзя считать секретным. Решение о продолжении принимается по протоколу и достаточной статистике, не по одному биту.'), 'Контроль ошибки расходует часть сырых данных и ещё не даёт готового ключа.', 'После раскрытия одной позиции остаётся не более трёх нераскрытых битов, до исправления ошибок и усиления секретности.', 'Четыре бита — демонстрация учёта, не достаточная выборка для оценки безопасности. Классический канал должен быть аутентифицирован.'),
 'BB84': e('Алиса: биты [0,1,1,0], базисы [+,×,+,×]. Боб выбирает [+,+,+,×]; идеальный канал без перехвата.', ('Сравнить только базисы: совпали позиции 1,3,4; позицию 2 отбросить.', 'На совпавших базисах Боб получает [0,1,0]. Алиса оставляет те же биты.'), 'Просеянная последовательность 010, длина 3.', 'Измерение позиции 2 в другом базисе не используется как достоверный общий бит.', 'Сырые совпавшие биты ещё не окончательный секретный ключ: нужны оценка ошибок, согласование и усиление секретности.'),
 'Post-Quantum Cryptography': e('Система использует классический обмен ключами и классическую подпись. Требуется оценить замену обмена на постквантовый KEM.', ('Разделить назначение механизмов: KEM получает общий секрет, подпись подтверждает сообщения.', 'Проверить, как новый общий секрет включается в существующий протокол и чем аутентифицируется обмен.', 'Отдельно оценить подпись: замена KEM не сделала её автоматически постквантовой.'), 'Получен перечень двух независимых миграционных задач, а не одна замена названия алгоритма.', 'В схеме явно остались два поля: механизм согласования секрета и механизм аутентификации.', 'Конкретные статусы стандартов и выбор параметров требуют актуальной проверки; эта карточка не объявляет старые результаты курса современным рейтингом.'),
 'Hash-Based Signatures': e('Миниатюрная схема Лэмпорта для двухбитного сообщения 10. Для каждой позиции подготовлены два разных секрета: x00,x01 и x10,x11; опубликованы их хеши.', ('Для первого бита 1 раскрыть x01, для второго бита 0 —x10.', 'Проверяющий хеширует оба раскрытых значения и сравнивает с публичными h01 и h10.'), 'Подпись раскрывает ровно один секрет из каждой пары.', 'Повторная подпись 01 тем же ключом раскрыла бы оставшиеся x00 и x11; теперь известны все четыре секрета и можно подписать 00 или 11.', 'Значения обозначены символами, потому что демонстрируется поток раскрытия, не вычисление конкретного хеша. Это одноразовая подпись; размер сообщения здесь учебный.'),
 'Code-Based Cryptography': e('Учебный повторительный код: 0→000, 1→111. Передан бит 1, канал изменил второй разряд: получено 101.', ('Расстояние до 111 равно 1, до 000 равно 2.', 'Декодер ближайшего слова выбирает 111 и возвращает 1.'), 'Одна ошибка исправлена за счёт избыточности.', 'При двух ошибках 111→001 декодер выберет 000 и ошибётся: радиус исправления здесь только 1.', 'Этот открытый код не является McEliece/Niederreiter. Он поясняет декодирование; криптографическая трудность требует совсем другой структуры и параметров.'),
 'Lattice-Based Cryptography': e('Базис b1=(2,0),b2=(1,3), целые коэффициенты z1=2,z2=−1.', ('Вектор решётки v=2b1−b2=(4,0)−(1,3)=(3,−3).', 'Для точки t=(3.2,−2.8) расстояние до v равно √(0.2²+0.2²)=√0.08≈0.282843.'), 'v принадлежит решётке, t — нет: вторая координата точек решётки кратна 3.', 'Подстановка целых коэффициентов восстанавливает v. Дробные коэффициенты описывают линейную оболочку, не обязательно решётку.', 'Ближайшая точка в этом маленьком примере наглядна; он не доказывает трудность LWE/SIS и не задаёт безопасные параметры.'),
 'Multivariate Cryptography': e('Система над F5: f1(x,y)=x²+y, f2(x,y)=x+y²; вход x=2,y=3.', ('f1=4+3=7≡2 mod 5.', 'f2=2+9=11≡1 mod 5; образ равен (2,1).'), 'Прямое вычисление системы даёт два выходных элемента поля.', 'Вход (0,2) также даёт (2,4), а не (2,1); кандидат прообраза проверяется подстановкой в обе формулы.', 'Не всякая квадратичная система является односторонней или задаёт подпись. На F5 полный перебор всего 25 пар, поэтому криптографической защиты здесь нет.'),
 'Brute-Force Attack': e('Учебный ключ из k=4 бит, 16 кандидатов. Перебор фиксирован от 0 до 15; истинный ключ равномерный.', ('Число проверок до успеха принимает значения 1…16.', 'Среднее (1+16)/2=8.5; максимум 16. При грубой оценке используется 2^(k−1)=8.'), 'Точная средняя стоимость при этих условиях 8.5 проверок, а 8 — приближение.', 'Сумма 1+…+16=136, деление на 16 даёт 8.5.', 'Среднее меняется при неравномерных ключах и иной модели проверки; пароль из человеческого словаря не равномерный k-битный ключ.'),
 'Linear Cryptanalysis': e('Игрушечная перестановка 3-битных чисел S=[0,1,3,6,7,4,5,2]. Проверяем равенство младшего бита входа и выхода.', ('Совпадения только для x=0,1; всего 2 из 8. Например, x=5 имеет младший бит 1, но S(5)=4 имеет младший бит 0.', 'P=2/8=0.25, смещение epsilon=P−0.5=−0.25.'), 'Соотношение выполняется реже половины случаев; отрицательное смещение тоже отличает его от равновероятного.', 'Перебраны все входы, а не случайная малая выборка; для противоположного равенства вероятность 6/8 и смещение +0.25.', 'Корреляция одной пары масок не определяет стойкость многораундового шифра. Это таблица одного игрушечного преобразования, не атака на реальный шифр.'),
 'Differential Cryptanalysis': e('Тот же учебный S=[0,1,3,6,7,4,5,2], разность входов DeltaX=1.', ('Для пар x и x XOR 1 выходные XOR-разности по x=0…7: [1,1,5,5,3,3,7,7].', 'Каждое из значений 1,3,5,7 встречается дважды из восьми входов, остальные — ноль.'), 'Например, переход 1→5 имеет вероятность 2/8=1/4.', 'Сумма всех счётчиков строки DDT равна 8, сумма вероятностей 1.', 'Одна строка DDT не определяет стойкость многораундового шифра; для склейки характеристик нужны дополнительные предположения.'),
 'Side-Channel Attacks': e('Учебная процедура сравнения двухбайтового секрета останавливается на первом несовпавшем байте. Считаем только число сравнений, без реального измерения времени.', ('Кандидат с неверным первым байтом требует одно сравнение.', 'Кандидат с верным первым и неверным вторым требует два; наблюдатель различает эти случаи по заданной модели утечки.'), 'Промежуточное совпадение раскрывается без получения успешного ответа.', 'Процедура, всегда сравнивающая оба байта, устраняет именно эту разницу количества сравнений.', 'Равное число операций ещё не доказывает постоянное время на конкретной платформе; реальные утечки и шум нужно измерять отдельно.'),
 'Man-in-the-Middle Attack': e('Алиса и Боб выполняют неаутентифицированный DH; посредник М может заменить оба публичных значения.', ('Вместо ключа Боба Алиса получает значение М и согласует секрет K_AM.', 'Вместо ключа Алисы Боб получает другое значение М и согласует K_MB.', 'М расшифровывает сообщение под K_AM и повторно шифрует под K_MB.'), 'Обе стороны видят работающий защищённый канал, но не друг с другом.', 'Проверка подписи транскрипта доверенным ключом ожидаемого участника разрывает именно подмену публичных значений.', 'Сценарий требует активного контроля канала и отсутствия аутентификации, а не просто возможности читать сетевые пакеты.'),
 'Russian Cryptographic Regulation and Certification': e('Организация рассматривает средство версии A; в доступном ей документе соответствия указана версия B и конкретная комплектация.', ('Сопоставить версию, исполнение и условия эксплуатации: A не совпадает с B.', 'Не делать вывод о соответствии A только по общему названию продукта; запросить подтверждение применимости документа к выбранной конфигурации.'), 'Зафиксирован пробел в подтверждающих документах, а не юридический вывод о допустимости средства.', 'В таблице сопоставления отдельно стоят версия, комплектация, условия и область действия документа.', 'Сценарий условный и не утверждает действующих требований. Карточка сохраняет status: review; сведения DOCX датированы апрелем 2025 года и требуют актуальной проверки.'),
}
